# Formula for the swarm CLI.
#
# Generated by GoReleaser on tag releases (see .goreleaser.yaml `brews`
# in the hyperengineering/swarm repo); this hand-written copy covers
# v0.8.0-beta.1. The darwin binaries live in this repository under
# binaries/ (raw URLs) because hyperengineering/swarm is private and
# its release assets are not publicly fetchable.
class Swarm < Formula
  desc "Swarm CLI — provision VMs and deploy devcontainers"
  homepage "https://github.com/hyperengineering/swarm"
  version "0.8.0-beta.1"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/hyperengineering/homebrew-tap/raw/main/binaries/swarm_0.8.0-beta.1_darwin_arm64.tar.gz"
      sha256 "aa5769f036d9ba1bfdf8065923c82aeef3565b4e17b6e049eb4f979dc6b25bf2"
    end
    if Hardware::CPU.intel?
      url "https://github.com/hyperengineering/homebrew-tap/raw/main/binaries/swarm_0.8.0-beta.1_darwin_amd64.tar.gz"
      sha256 "2e1f3dadbad1a4633d531df1c7604eca6b06469c39998c60f9da6af7e4afbed1"
    end
  end

  def install
    bin.install "swarm"
  end

  test do
    system "#{bin}/swarm", "version"
  end
end
